    public boolean isBipartite()
    {
        if (isEmpty(graph)) {
            return true;
        }
        try {
            if (Math.multiplyExact(4, graph.edgeSet().size()) > Math
                .multiplyExact(graph.vertexSet().size(), graph.vertexSet().size()))
            {
                return false;
            }
        } catch (ArithmeticException e) {
        }
        return this.getPartitioning() != null;
}
}
