  public String[] getMRUFileList() {
    if (size() == 0) {
      return null;
    }
    String[] ss = new String[size()];
    for (int i = 0; i < size(); i++) {
      Object o = getFile(i);
      if (o instanceof File) {
        ss[i] = ((File) o).getAbsolutePath();
      } else
      {
        ss[i] = o.toString();
      }
    }
    return ss;
}
}
