    public void removeEdge(BlossomVEdge edge, int dir)
    {
        if (edge.prev[dir] == edge) {
            first[dir] = null;
        } else {
            edge.prev[dir].next[dir] = edge.next[dir];
            edge.next[dir].prev[dir] = edge.prev[dir];
            if (first[dir] == edge) {
                first[dir] = edge.next[dir];
            }
        }
}
