    private static String decodeQueryParam(String s, int n) {
        final StringBuilder sb = new StringBuilder(n);
        ByteBuffer bb = null;
        for (int i = 0; i < n;) {
            final char c = s.charAt(i++);
            if (c != '%') {
                if (c != '+')
                    sb.append(c);
                else
                    sb.append(' ');
            } else {
                bb = decodePercentEncodedOctets(s, i, bb);
                i = decodeOctets(i, bb, sb);
            }
        }
        return sb.toString();
}
}
