    private void getFiles(File f) {
        if (scanDone) return;
        File[] files = f.listFiles();
        for (File test : Objects.requireNonNull(files)) {
            if (test.isDirectory()) {
                getFiles(test);
            } else {
                String clazz = test.getAbsolutePath();
                if (clazz.endsWith(".class")) {
                    possibleComponentsCandidate.add(clazz);
                }
            }
        }
}
}
