        public static String base64EncodeFoArray(final byte[] s) {
            if (s == null) {
                return null;
            }
            if (s.length == 0) {
                return "";
            }
            StringBuffer buf = new StringBuffer();
            int b0, b1, b2, b3;
            int len = s.length;
            int i = 0;
            while (i < len) {
                byte tmp = s[i++];
                b0 = (tmp & 0xfc) >> 2;
                b1 = (tmp & 0x03) << 4;
                if (i < len) {
                    tmp = s[i++];
                    b1 |= (tmp & 0xf0) >> 4;
                    b2 = (tmp & 0x0f) << 2;
                    if (i < len) {
                        tmp = s[i++];
                        b2 |= (tmp & 0xc0) >> 6;
                        b3 = tmp & 0x3f;
                    } else {
                        b3 = 64;
                    }
                } else {
                    b2 = b3 = 64;
                }
                buf.append(Base64.Base64Chars.charAt(b0));
                buf.append(Base64.Base64Chars.charAt(b1));
                buf.append(Base64.Base64Chars.charAt(b2));
                buf.append(Base64.Base64Chars.charAt(b3));
            }
            return buf.toString();
}
}
