    public static <V, E> boolean isK33Subdivision(Graph<V, E> graph)
    {
        List<V> degree3 = new ArrayList<>();
        for (V vertex : graph.vertexSet()) {
            int degree = graph.degreeOf(vertex);
            if (degree == 3) {
                degree3.add(vertex);
            } else if (degree != 2) {
                return false;
            }
        }
        if (degree3.size() != 6) {
